revoke execute on function "better_supabase"."delete_supplier_item_mapping"(uuid, uuid) from public, anon;
grant execute on function "better_supabase"."delete_supplier_item_mapping"(uuid, uuid) to authenticated, service_role;

-- One source row of a supplier's price list as supplier item fields, through
-- the supplier's mapping. price is in minor units: the source value is a
-- decimal in major units, with a comma or a dot as the decimal separator.
create or replace function "better_supabase"."supplier_item_from_row"(tenant uuid, supplier uuid, source jsonb)
returns jsonb
language plpgsql
stable
security invoker
set search_path = ''
as $$
declare
  v_columns jsonb;
  v_defaults jsonb;
  v_code text;
  v_description text;
  v_unit text;
  v_currency text;
  v_price text;
  v_amount bigint;
  v_scale integer;
  v_keywords text;
  v_source jsonb;
begin
  select x."columns", x."defaults" into v_columns, v_defaults
  from "better_supabase"."supplier_item_mappings" x where x."tenant_id" = supplier_item_from_row.tenant and x."supplier_id" = supplier_item_from_row.supplier;
  if v_columns is null then
    raise exception 'this supplier has no column mapping' using errcode = 'P0002', hint = 'CATALOG_SUPPLIER_MAPPING_NOT_FOUND';
  end if;
  if jsonb_typeof(supplier_item_from_row.source) is distinct from 'object' then
    raise exception 'a row is an object of source columns' using errcode = '22023', hint = 'CATALOG_SUPPLIER_ROW_INVALID';
  end if;
  v_code := nullif(btrim(supplier_item_from_row.source ->> (v_columns ->> 'code')), '');
  v_description := nullif(btrim(supplier_item_from_row.source ->> (v_columns ->> 'description')), '');
  v_unit := coalesce(nullif(btrim(supplier_item_from_row.source ->> (v_columns ->> 'unit')), ''), v_defaults ->> 'unit');
  v_currency := upper(coalesce(nullif(btrim(supplier_item_from_row.source ->> (v_columns ->> 'currency')), ''), v_defaults ->> 'currency'));
  v_price := nullif(btrim(supplier_item_from_row.source ->> (v_columns ->> 'price')), '');
  if v_currency is not null and "better_supabase"."currency_minor_units"(v_currency) is null then
    raise exception 'not an ISO 4217 currency code' using errcode = '22023', hint = 'CATALOG_CURRENCY_INVALID';
  end if;
  if v_price is not null then
    v_price := regexp_replace(v_price, '[^0-9.,-]', '', 'g');
    if position(',' in v_price) > 0 and position('.' in v_price) > 0 then
      -- The separator that comes last is the decimal one.
      if length(v_price) - length(regexp_replace(v_price, '^.*,', '')) > length(v_price) - length(regexp_replace(v_price, '^.*\.', '')) then
        v_price := replace(replace(v_price, '.', ''), ',', '.');
      else
        v_price := replace(v_price, ',', '');
      end if;
    else
      v_price := replace(v_price, ',', '.');
    end if;
    v_scale := coalesce("better_supabase"."currency_minor_units"(v_currency), 2);
    begin
      v_amount := round(v_price::numeric * power(10::numeric, v_scale))::bigint;
    exception when others then
      raise exception 'the price is not a number' using errcode = '22023', hint = 'CATALOG_SUPPLIER_PRICE_INVALID';
    end;
    if v_amount < 0 then
      raise exception 'the price can''t be negative' using errcode = '22023', hint = 'CATALOG_SUPPLIER_PRICE_INVALID';
    end if;
  end if;
  v_source := case jsonb_typeof(v_columns -> 'keywords') when 'array' then v_columns -> 'keywords' when 'string' then jsonb_build_array(v_columns -> 'keywords') else '[]'::jsonb end;
  select nullif(string_agg(btrim(supplier_item_from_row.source ->> (a.value #>> '{}')), ' ') filter (where nullif(btrim(supplier_item_from_row.source ->> (a.value #>> '{}')), '') is not null), '')
  into v_keywords from jsonb_array_elements(v_source) a;
  return jsonb_strip_nulls(jsonb_build_object('code', v_code, 'description', v_description, 'price', v_amount, 'currency', v_currency, 'unit', v_unit, 'keywords', v_keywords));
end;
$$;
revoke execute on function "better_supabase"."supplier_item_from_row"(uuid, uuid, jsonb) from public, anon;
grant execute on function "better_supabase"."supplier_item_from_row"(uuid, uuid, jsonb) to authenticated, service_role;

-- Creates a supplier item (item null) or updates one; on an update a null
-- argument keeps the column. price is in minor units.
create or replace function "better_supabase"."save_supplier_item"(tenant uuid, item uuid, supplier uuid, code text, description text, price bigint, currency text, unit text, keywords text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid := save_supplier_item.item;
  v_code text := btrim(save_supplier_item.code);
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', save_supplier_item.tenant, 'catalog.manage'), false)) then
    raise exception 'not allowed to manage the catalog' using errcode = '42501', hint = 'CATALOG_FORBIDDEN';
  end if;
  if v_code is null or length(v_code) not between 1 and 100 then
    raise exception 'the code must be 1 to 100 characters' using errcode = '22023', hint = 'CATALOG_SUPPLIER_ITEM_INVALID';
  end if;
  if save_supplier_item.price is not null and save_supplier_item.price < 0 then
    raise exception 'the price can''t be negative' using errcode = '22023', hint = 'CATALOG_SUPPLIER_ITEM_INVALID';
  end if;
  if save_supplier_item.currency is not null and "better_supabase"."currency_minor_units"(save_supplier_item.currency) is null then
    raise exception 'not an ISO 4217 currency code' using errcode = '22023', hint = 'CATALOG_CURRENCY_INVALID';
  end if;
  begin
    if v_id is null then
      insert into "better_supabase"."supplier_items" as x ("tenant_id", "supplier_id", "code", "description", "price", "currency", "unit", "keywords_text")
      values (save_supplier_item.tenant, save_supplier_item.supplier, v_code, save_supplier_item.description, save_supplier_item.price, save_supplier_item.currency, save_supplier_item.unit, save_supplier_item.keywords)
      returning x."id" into v_id;
    else
      update "better_supabase"."supplier_items" x set "supplier_id" = coalesce(save_supplier_item.supplier, x."supplier_id"), "code" = v_code,
        "description" = coalesce(save_supplier_item.description, x."description"), "price" = coalesce(save_supplier_item.price, x."price"),
        "currency" = coalesce(save_supplier_item.currency, x."currency"), "unit" = coalesce(save_supplier_item.unit, x."unit"),
        "keywords_text" = coalesce(save_supplier_item.keywords, x."keywords_text"), "updated_at" = now()
      where x."id" = save_supplier_item.item and x."tenant_id" = save_supplier_item.tenant;
      if not found then
        raise exception 'supplier item not found' using errcode = 'P0002', hint = 'CATALOG_SUPPLIER_ITEM_NOT_FOUND';
      end if;
    end if;
  exception when unique_violation then
    raise exception 'this supplier already has an item with this code' using errcode = '23505', hint = 'CATALOG_SUPPLIER_ITEM_TAKEN';
  end;
  return jsonb_build_object('id', v_id, 'code', v_code);
end;
$$;
revoke execute on function "better_supabase"."save_supplier_item"(uuid, uuid, uuid, text, text, bigint, text, text, text) from public, anon;
grant execute on function "better_supabase"."save_supplier_item"(uuid, uuid, uuid, text, text, bigint, text, text, text) to authenticated, service_role;

-- Deletes a supplier item. The variant it was promoted to stays.
create or replace function "better_supabase"."delete_supplier_item"(item uuid)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tenant uuid;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select x."tenant_id" into v_tenant from "better_supabase"."supplier_items" x where x."id" = delete_supplier_item.item;
  if v_tenant is null then
    return false;
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_tenant, 'catalog.manage'), false)) then
    raise exception 'not allowed to manage the catalog' using errcode = '42501', hint = 'CATALOG_FORBIDDEN';
  end if;
  delete from "better_supabase"."supplier_items" x where x."id" = delete_supplier_item.item;
  return true;
end;
$$;
revoke execute on function "better_supabase"."delete_supplier_item"(uuid) from public, anon;
grant execute on function "better_supabase"."delete_supplier_item"(uuid) to authenticated, service_role;

-- Searches supplier items by words in the code, the description and the
-- keywords, and by the start of a code. The caller's read access limits the
-- rows; the best matches come first.
create or replace function "better_supabase"."search_supplier_items"(tenant uuid, query text, supplier uuid default null, row_limit integer default 25)
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
  select coalesce(jsonb_agg(r.item order by r.rank desc, r.code), '[]'::jsonb)
  from (
    select x."code" as code,
      ts_rank(x."keywords", websearch_to_tsquery('simple', $2)) + case when x."code" ilike replace(replace($2, '%', ''), '_', '') || '%' then 1 else 0 end as rank,
      jsonb_build_object('id', x."id", 'supplierId', x."supplier_id", 'code', x."code", 'description', x."description", 'price', x."price", 'currency', x."currency", 'unit', x."unit", 'variantId', x."variant_id") as item
    from "better_supabase"."supplier_items" x
    where x."tenant_id" = $1 and ($3 is null or x."supplier_id" = $3)
      and (x."keywords" @@ websearch_to_tsquery('simple', $2) or x."code" ilike replace(replace($2, '%', ''), '_', '') || '%')
    order by 2 desc, 1
    limit least(greatest(coalesce($4, 25), 1), 200)
  ) r
$$;
revoke execute on function "better_supabase"."search_supplier_items"(uuid, text, uuid, integer) from public, anon;
grant execute on function "better_supabase"."search_supplier_items"(uuid, text, uuid, integer) to authenticated, service_role;

-- Makes a supplier item a catalog product on first use: a product and a variant
-- (sku defaults to the supplier's code), the supplier's code as an identifier,
-- and the link back on the item. A second call returns the same variant with
-- created false.
create or replace function "better_supabase"."promote_supplier_item"(item uuid, sku text default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_item "better_supabase"."supplier_items";
  v_sku text;
  v_slug text;
  v_product uuid;
  v_variant uuid;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_item from "better_supabase"."supplier_items" x where x."id" = promote_supplier_item.item for update;
  if not found then
    raise exception 'supplier item not found' using errcode = 'P0002', hint = 'CATALOG_SUPPLIER_ITEM_NOT_FOUND';
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_item."tenant_id", 'catalog.manage'), false)) then
    raise exception 'not allowed to manage the catalog' using errcode = '42501', hint = 'CATALOG_FORBIDDEN';
  end if;
  if v_item."variant_id" is not null then
    select y."product_id" into v_product from "better_supabase"."product_variants" y where y."id" = v_item."variant_id";
    return jsonb_build_object('productId', v_product, 'variantId', v_item."variant_id", 'created', false);
  end if;
  v_sku := btrim(coalesce(nullif(promote_supplier_item.sku, ''), v_item."code"));
  if length(v_sku) not between 1 and 100 then
    raise exception 'the SKU must be 1 to 100 characters' using errcode = '22023', hint = 'CATALOG_SKU_INVALID';
  end if;
  v_slug := trim(both '-' from regexp_replace(lower(v_sku), '[^a-z0-9]+', '-', 'g'));
  if v_slug = '' then
    v_slug := 'item';
  end if;
  if exists (select 1 from "better_supabase"."products" x where x."tenant_id" = v_item."tenant_id" and x."slug" = v_slug) then
    v_slug := v_slug || '-' || substr(v_item."id"::text, 1, 8);
  end if;
  begin
    insert into "better_supabase"."products" as x ("tenant_id", "title", "slug", "description")
    values (v_item."tenant_id", left(coalesce(nullif(v_item."description", ''), v_item."code"), 500), v_slug, v_item."description")
    returning x."id" into v_product;
    insert into "better_supabase"."product_variants" as y ("tenant_id", "product_id", "sku")
    values (v_item."tenant_id", v_product, v_sku)
    returning y."id" into v_variant;
  exception when unique_violation then
    raise exception 'another variant has this SKU' using errcode = '23505', hint = 'CATALOG_SKU_TAKEN';
  end;
  update "better_supabase"."supplier_items" x set "variant_id" = v_variant, "updated_at" = now() where x."id" = v_item."id";
  insert into "better_supabase"."product_identifiers" ("tenant_id", "variant_id", "type", "value", "party_id")
  values (v_item."tenant_id", v_variant, 'supplier', v_item."code", v_item."supplier_id")
  on conflict do nothing;
  perform "better_supabase".emit_event('product.created', jsonb_build_object('organizationId', v_item."tenant_id", 'id', v_product, 'slug', v_slug, 'kind', null), 'products/' || v_product::text, (v_item."tenant_id")::text, null, 'better-supabase/catalog');
  perform "better_supabase".emit_event('product_variant.created', jsonb_build_object('organizationId', v_item."tenant_id", 'id', v_variant, 'productId', v_product, 'sku', v_sku), 'variants/' || v_variant::text, (v_item."tenant_id")::text, null, 'better-supabase/catalog');
  return jsonb_build_object('productId', v_product, 'variantId', v_variant, 'created', true);
end;
$$;
revoke execute on function "better_supabase"."promote_supplier_item"(uuid, text) from public, anon;
grant execute on function "better_supabase"."promote_supplier_item"(uuid, text) to authenticated, service_role;

-- Sets a variant's Combined Nomenclature code (4 to 10 digits; spaces are
-- dropped), or clears it with null.
create or replace function "better_supabase"."set_variant_trade_code"(variant uuid, trade_code text)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tenant uuid;
  v_code text := nullif(replace(btrim(set_variant_trade_code.trade_code), ' ', ''), '');
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select x."tenant_id" into v_tenant from "better_supabase"."product_variants" x where x."id" = set_variant_trade_code.variant;
  if v_tenant is null then
    raise exception 'variant not found' using errcode = 'P0002', hint = 'CATALOG_VARIANT_NOT_FOUND';
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_tenant, 'catalog.manage'), false)) then
    raise exception 'not allowed to manage the catalog' using errcode = '42501', hint = 'CATALOG_FORBIDDEN';
  end if;
  if v_code is not null and v_code !~ '^[0-9]{4,10}$' then
    raise exception 'a trade code has 4 to 10 digits' using errcode = '22023', hint = 'CATALOG_TRADE_CODE_INVALID';
  end if;
  update "better_supabase"."product_variants" x set "trade_code" = v_code, "updated_at" = now() where x."id" = set_variant_trade_code.variant;
  return true;
end;
$$;
revoke execute on function "better_supabase"."set_variant_trade_code"(uuid, text) from public, anon;
grant execute on function "better_supabase"."set_variant_trade_code"(uuid, text) to authenticated, service_role;

-- The import target of the supplier_item entity (ADR 0141): item.data is {
-- supplierId, row?, code?, description?, price?, currency?, unit?, keywords? }.
-- A row goes through the supplier's column mapping; the fields named next to
-- it win. price is in minor units. A key that is new but names a code the
-- supplier already has takes over that row.
create or replace function "better_supabase"."import_supplier_item"(run uuid, item jsonb, subject_id text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tenant uuid := (import_supplier_item.item ->> 'tenant')::uuid;
  v_data jsonb := import_supplier_item.item -> 'data';
  v_supplier uuid;
  v_merged jsonb;
  v_code text;
  v_price text;
  v_id uuid;
  v_updated timestamptz;
begin
  begin
    v_supplier := nullif(v_data ->> 'supplierId', '')::uuid;
  exception when invalid_text_representation then
    raise exception 'supplierId must be a uuid' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end;
  if v_supplier is null then
    raise exception 'a supplier item needs a supplierId' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  v_merged := (case when jsonb_typeof(v_data -> 'row') = 'object' then "better_supabase"."supplier_item_from_row"(v_tenant, v_supplier, v_data -> 'row') else '{}'::jsonb end) || (v_data - 'row' - 'supplierId');
  v_code := nullif(btrim(v_merged ->> 'code'), '');
  v_price := v_merged ->> 'price';
  if v_code is null or length(v_code) > 100 then
    raise exception 'a supplier item needs a code of up to 100 characters' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if v_price is not null and v_price !~ '^[0-9]{1,18}$' then
    raise exception 'price is a whole number of minor units' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if v_merged ->> 'currency' is not null and "better_supabase"."currency_minor_units"(upper(v_merged ->> 'currency')) is null then
    raise exception 'not an ISO 4217 currency code' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if import_supplier_item.subject_id is null then
    insert into "better_supabase"."supplier_items" as x ("tenant_id", "supplier_id", "code", "description", "price", "currency", "unit", "keywords_text")
    values (v_tenant, v_supplier, v_code, v_merged ->> 'description', v_price::bigint, upper(v_merged ->> 'currency'), v_merged ->> 'unit', v_merged ->> 'keywords')
    on conflict ("tenant_id", "supplier_id", "code") do update set "description" = excluded."description", "price" = excluded."price",
      "currency" = excluded."currency", "unit" = excluded."unit", "keywords_text" = excluded."keywords_text", "updated_at" = now()
    returning x."id", x."updated_at" into v_id, v_updated;
  else
    update "better_supabase"."supplier_items" x set "supplier_id" = v_supplier, "code" = v_code, "description" = v_merged ->> 'description', "price" = v_price::bigint,
      "currency" = upper(v_merged ->> 'currency'), "unit" = v_merged ->> 'unit', "keywords_text" = v_merged ->> 'keywords', "updated_at" = now()
    where x."id" = import_supplier_item.subject_id::uuid and x."tenant_id" = v_tenant
    returning x."id", x."updated_at" into v_id, v_updated;
    if not found then
      raise exception 'the supplier item no longer exists' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
    end if;
  end if;
  return jsonb_build_object('subjectId', v_id::text, 'updatedAt', v_updated);
end;
$$;
revoke execute on function "better_supabase"."import_supplier_item"(uuid, jsonb, text) from public, anon, authenticated;
grant execute on function "better_supabase"."import_supplier_item"(uuid, jsonb, text) to service_role;

-- When a supplier item last changed, for the conflict check of imports.
create or replace function "better_supabase"."supplier_item_updated_at"(subject_id text)
returns timestamptz
language sql
stable
security definer
set search_path = ''
as $$
  select x."updated_at" from "better_supabase"."supplier_items" x where x."id" = $1::uuid
$$;
revoke execute on function "better_supabase"."supplier_item_updated_at"(text) from public, anon, authenticated;
grant execute on function "better_supabase"."supplier_item_updated_at"(text) to service_role;

-- The import target of the product_identifier entity: item.data is { sku or
-- variantId, type, value, partyId? }. A key that is new but names a code the
-- variant already has takes over that row.
create or replace function "better_supabase"."import_product_identifier"(run uuid, item jsonb, subject_id text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tenant uuid := (import_product_identifier.item ->> 'tenant')::uuid;
  v_data jsonb := import_product_identifier.item -> 'data';
  v_variant uuid;
  v_type text := v_data ->> 'type';
  v_value text := btrim(v_data ->> 'value');
  v_party uuid;
  v_id uuid;
  v_updated timestamptz;
begin
  begin
    v_variant := nullif(v_data ->> 'variantId', '')::uuid;
    v_party := nullif(v_data ->> 'partyId', '')::uuid;
  exception when invalid_text_representation then
    raise exception 'variantId and partyId must be uuids' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end;
  if v_variant is null and nullif(v_data ->> 'sku', '') is not null then
    select y."id" into v_variant from "better_supabase"."product_variants" y where y."tenant_id" = v_tenant and y."sku" = v_data ->> 'sku';
  end if;
  if v_variant is null or not exists (select 1 from "better_supabase"."product_variants" y where y."id" = v_variant and y."tenant_id" = v_tenant) then
    raise exception 'the variant isn''t in this organization; name it with sku or variantId' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if v_type is null or v_type not in ('ean', 'supplier', 'manufacturer', 'other') then
    raise exception 'the type must be one of ean, supplier, manufacturer, other' using errcode = '22023', hint = 'CATALOG_IDENTIFIER_TYPE_INVALID';
  end if;
  if v_value is null or length(v_value) not between 1 and 100 then
    raise exception 'the value must be 1 to 100 characters' using errcode = '22023', hint = 'CATALOG_IDENTIFIER_INVALID';
  end if;
  if v_type = 'ean' and v_value !~ '^([0-9]{8}|[0-9]{12,14})$' then
    raise exception 'an EAN has 8, 12, 13 or 14 digits' using errcode = '22023', hint = 'CATALOG_IDENTIFIER_INVALID';
  end if;
  if import_product_identifier.subject_id is null then
    insert into "better_supabase"."product_identifiers" as x ("tenant_id", "variant_id", "type", "value", "party_id")
    values (v_tenant, v_variant, v_type, v_value, v_party)
    on conflict ("variant_id", "type", "value", coalesce("party_id", '00000000-0000-0000-0000-000000000000'::uuid)) do update set "updated_at" = now()
    returning x."id", x."updated_at" into v_id, v_updated;
  else
    update "better_supabase"."product_identifiers" x set "variant_id" = v_variant, "type" = v_type, "value" = v_value, "party_id" = v_party, "updated_at" = now()
    where x."id" = import_product_identifier.subject_id::uuid and x."tenant_id" = v_tenant
    returning x."id", x."updated_at" into v_id, v_updated;
    if not found then
      raise exception 'the identifier no longer exists' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
    end if;
  end if;
  return jsonb_build_object('subjectId', v_id::text, 'updatedAt', v_updated);
end;
$$;
revoke execute on function "better_supabase"."import_product_identifier"(uuid, jsonb, text) from public, anon, authenticated;
grant execute on function "better_supabase"."import_product_identifier"(uuid, jsonb, text) to service_role;

create or replace function "better_supabase"."product_identifier_updated_at"(subject_id text)
returns timestamptz
language sql
stable
security definer
set search_path = ''
as $$
  select x."updated_at" from "better_supabase"."product_identifiers" x where x."id" = $1::uuid
$$;
revoke execute on function "better_supabase"."product_identifier_updated_at"(text) from public, anon, authenticated;
grant execute on function "better_supabase"."product_identifier_updated_at"(text) to service_role;

-- Creates a discount group (group null) or renames one. kind is customer or
-- product and can't change; the code is unique per tenant and kind. Returns
-- its id and whether it was created.
create or replace function "better_supabase"."save_discount_group"(tenant uuid, "group" uuid, kind text, code text, name text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
  v_created boolean := save_discount_group."group" is null;
  v_code text := btrim(save_discount_group.code);
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', save_discount_group.tenant, 'catalog.manage'), false)) then
    raise exception 'not allowed to manage the catalog' using errcode = '42501', hint = 'CATALOG_FORBIDDEN';
  end if;
  if save_discount_group.kind is null or save_discount_group.kind not in ('customer', 'product') then
    raise exception 'the kind is customer or product' using errcode = '22023', hint = 'CATALOG_DISCOUNT_GROUP_INVALID';
  end if;
  if v_code is null or length(v_code) not between 1 and 50 or length(btrim(coalesce(save_discount_group.name, ''))) not between 1 and 200 then
    raise exception 'a group needs a code of up to 50 and a name of up to 200 characters' using errcode = '22023', hint = 'CATALOG_DISCOUNT_GROUP_INVALID';
  end if;
  begin
    if v_created then
      insert into "better_supabase"."discount_groups" as x ("tenant_id", "kind", "code", "name")
      values (save_discount_group.tenant, save_discount_group.kind, v_code, btrim(save_discount_group.name))
      returning x."id" into v_id;
    else
      update "better_supabase"."discount_groups" x set "code" = v_code, "name" = btrim(save_discount_group.name), "updated_at" = now()
      where x."id" = save_discount_group."group" and x."tenant_id" = save_discount_group.tenant and x."kind" = save_discount_group.kind
      returning x."id" into v_id;
      if v_id is null then
        raise exception 'discount group not found' using errcode = 'P0002', hint = 'CATALOG_DISCOUNT_GROUP_NOT_FOUND';
      end if;
    end if;
  exception when unique_violation then
    raise exception 'a group of this kind already has this code' using errcode = '23505', hint = 'CATALOG_DISCOUNT_GROUP_EXISTS';
  end;
  return jsonb_build_object('id', v_id, 'created', v_created);
end;
$$;
revoke execute on function "better_supabase"."save_discount_group"(uuid, uuid, text, text, text) from public, anon;
grant execute on function "better_supabase"."save_discount_group"(uuid, uuid, text, text, text) to authenticated, service_role;

-- Deletes a group no rule uses. Its customers leave it and its variants lose
-- the group.
create or replace function "better_supabase"."delete_discount_group"("group" uuid)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tenant uuid;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select x."tenant_id" into v_tenant from "better_supabase"."discount_groups" x where x."id" = delete_discount_group."group";
  if v_tenant is null then
    return false;
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_tenant, 'catalog.manage'), false)) then
    raise exception 'not allowed to manage the catalog' using errcode = '42501', hint = 'CATALOG_FORBIDDEN';
  end if;
  if exists (select 1 from "better_supabase"."discount_rules" y where y."customer_group_id" = delete_discount_group."group" or y."product_group_id" = delete_discount_group."group") then
    raise exception 'a rule of the matrix still uses this group' using errcode = '23503', hint = 'CATALOG_DISCOUNT_GROUP_IN_USE';
  end if;
  delete from "better_supabase"."discount_groups" x where x."id" = delete_discount_group."group";
  return true;
end;
$$;
revoke execute on function "better_supabase"."delete_discount_group"(uuid) from public, anon;
grant execute on function "better_supabase"."delete_discount_group"(uuid) to authenticated, service_role;

-- Puts a party (a company or person id) in a customer group, or takes it out
-- with null. A party is in one group; setting another moves it.
create or replace function "better_supabase"."set_party_discount_group"(tenant uuid, party text, "group" uuid)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', set_party_discount_group.tenant, 'catalog.manage'), false)) then
    raise exception 'not allowed to manage the catalog' using errcode = '42501', hint = 'CATALOG_FORBIDDEN';
  end if;
  if set_party_discount_group.party is null or length(btrim(set_party_discount_group.party)) not between 1 and 200 then
    raise exception 'name the party by its id' using errcode = '22023', hint = 'CATALOG_DISCOUNT_PARTY_INVALID';
  end if;
  if set_party_discount_group."group" is null then
    delete from "better_supabase"."discount_group_parties" x where x."tenant_id" = set_party_discount_group.tenant and x."party_id" = btrim(set_party_discount_group.party);
    return true;
  end if;
  if not exists (select 1 from "better_supabase"."discount_groups" y where y."id" = set_party_discount_group."group" and y."tenant_id" = set_party_discount_group.tenant and y."kind" = 'customer') then
    raise exception 'a party takes a customer group of its organization' using errcode = 'P0002', hint = 'CATALOG_DISCOUNT_GROUP_NOT_FOUND';
  end if;
  insert into "better_supabase"."discount_group_parties" as x ("tenant_id", "group_id", "party_id")
  values (set_party_discount_group.tenant, set_party_discount_group."group", btrim(set_party_discount_group.party))
  on conflict ("tenant_id", "party_id") do update set "group_id" = excluded."group_id";
  return true;
end;
$$;
revoke execute on function "better_supabase"."set_party_discount_group"(uuid, text, uuid) from public, anon;
grant execute on function "better_supabase"."set_party_discount_group"(uuid, text, uuid) to authenticated, service_role;

-- Puts a variant in a product group, or takes it out with null.
create or replace function "better_supabase"."set_variant_discount_group"(variant uuid, "group" uuid)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tenant uuid;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select x."tenant_id" into v_tenant from "better_supabase"."product_variants" x where x."id" = set_variant_discount_group.variant;
  if v_tenant is null then
    raise exception 'variant not found' using errcode = 'P0002', hint = 'CATALOG_VARIANT_NOT_FOUND';
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_tenant, 'catalog.manage'), false)) then
    raise exception 'not allowed to manage the catalog' using errcode = '42501', hint = 'CATALOG_FORBIDDEN';
  end if;
  if set_variant_discount_group."group" is not null and not exists (
    select 1 from "better_supabase"."discount_groups" y where y."id" = set_variant_discount_group."group" and y."tenant_id" = v_tenant and y."kind" = 'product') then
    raise exception 'a variant takes a product group of its organization' using errcode = 'P0002', hint = 'CATALOG_DISCOUNT_GROUP_NOT_FOUND';
  end if;
  update "better_supabase"."product_variants" x set "discount_group_id" = set_variant_discount_group."group", "updated_at" = now() where x."id" = set_variant_discount_group.variant;
  return true;
end;
$$;
revoke execute on function "better_supabase"."set_variant_discount_group"(uuid, uuid) from public, anon;
grant execute on function "better_supabase"."set_variant_discount_group"(uuid, uuid) to authenticated, service_role;

-- The checks of a rule's attributes, shared by the function and the import.
create or replace function "better_supabase"."discount_rule_check"(tenant uuid, attrs jsonb)
returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_customer uuid;
  v_product uuid;
begin
  begin
    v_customer := nullif(discount_rule_check.attrs ->> 'customerGroupId', '')::uuid;
    v_product := nullif(discount_rule_check.attrs ->> 'productGroupId', '')::uuid;
    perform (discount_rule_check.attrs ->> 'validFrom')::date, (discount_rule_check.attrs ->> 'validTo')::date;
  exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow then
    raise exception 'group ids are uuids and dates are YYYY-MM-DD' using errcode = '22023', hint = 'CATALOG_DISCOUNT_RULE_INVALID';
  end;
  if v_customer is not null and not exists (select 1 from "better_supabase"."discount_groups" y where y."id" = v_customer and y."tenant_id" = discount_rule_check.tenant and y."kind" = 'customer') then
    raise exception 'customerGroupId isn''t a customer group of this organization' using errcode = 'P0002', hint = 'CATALOG_DISCOUNT_GROUP_NOT_FOUND';
  end if;
  if v_product is not null and not exists (select 1 from "better_supabase"."discount_groups" y where y."id" = v_product and y."tenant_id" = discount_rule_check.tenant and y."kind" = 'product') then
    raise exception 'productGroupId isn''t a product group of this organization' using errcode = 'P0002', hint = 'CATALOG_DISCOUNT_GROUP_NOT_FOUND';
  end if;
  if coalesce(discount_rule_check.attrs ->> 'discountBps', '0') !~ '^[0-9]{1,5}$' or coalesce(discount_rule_check.attrs ->> 'discountBps', '0')::integer > 10000 then
    raise exception 'discountBps is a whole number from 0 to 10000' using errcode = '22023', hint = 'CATALOG_DISCOUNT_RULE_INVALID';
  end if;
  if coalesce(discount_rule_check.attrs ->> 'minQuantity', '0') !~ '^[0-9]{1,14}([.][0-9]{1,4})?$' then
    raise exception 'minQuantity is zero or more' using errcode = '22023', hint = 'CATALOG_DISCOUNT_RULE_INVALID';
  end if;
  if (discount_rule_check.attrs ->> 'fixedPrice') is not null and discount_rule_check.attrs ->> 'fixedPrice' !~ '^[0-9]{1,18}$' then
    raise exception 'fixedPrice is a whole number of minor units' using errcode = '22023', hint = 'CATALOG_DISCOUNT_RULE_INVALID';
  end if;
  if ((discount_rule_check.attrs ->> 'fixedPrice') is null) <> ((discount_rule_check.attrs ->> 'currency') is null)
    or ((discount_rule_check.attrs ->> 'currency') is not null and (discount_rule_check.attrs ->> 'currency') !~ '^[A-Z]{3}$') then
    raise exception 'a fixed price comes with its ISO 4217 currency, and neither without the other' using errcode = '22023', hint = 'CATALOG_DISCOUNT_RULE_INVALID';
  end if;
  if (discount_rule_check.attrs ->> 'validFrom') is not null and (discount_rule_check.attrs ->> 'validTo') is not null
    and (discount_rule_check.attrs ->> 'validTo')::date < (discount_rule_check.attrs ->> 'validFrom')::date then
    raise exception 'validTo is on or after validFrom' using errcode = '22023', hint = 'CATALOG_DISCOUNT_RULE_INVALID';
  end if;
end;
$$;
revoke execute on function "better_supabase"."discount_rule_check"(uuid, jsonb) from public, anon, authenticated;

-- Creates a rule of the discount matrix (rule null) or replaces one. attrs: {
-- customerGroupId?, productGroupId?, validFrom?, validTo?, minQuantity?,
-- discountBps?, fixedPrice? (minor units as text), currency? }. A rule with the
-- same groups, start date and minimum quantity is one rule: the call updates
-- it. Returns its id and whether it was created.
create or replace function "better_supabase"."save_discount_rule"(tenant uuid, rule uuid, attrs jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_attrs jsonb := coalesce(save_discount_rule.attrs, '{}'::jsonb);
  v_id uuid;
  v_created boolean := true;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', save_discount_rule.tenant, 'catalog.manage'), false)) then
    raise exception 'not allowed to manage the catalog' using errcode = '42501', hint = 'CATALOG_FORBIDDEN';
  end if;
  perform "better_supabase"."discount_rule_check"(save_discount_rule.tenant, v_attrs);
  if save_discount_rule.rule is not null then
    update "better_supabase"."discount_rules" x set
      "customer_group_id" = nullif(v_attrs ->> 'customerGroupId', '')::uuid, "product_group_id" = nullif(v_attrs ->> 'productGroupId', '')::uuid,
      "valid_from" = (v_attrs ->> 'validFrom')::date, "valid_to" = (v_attrs ->> 'validTo')::date,
      "min_quantity" = coalesce((v_attrs ->> 'minQuantity')::numeric, 0), "discount_bps" = coalesce((v_attrs ->> 'discountBps')::integer, 0),
      "fixed_price" = (v_attrs ->> 'fixedPrice')::bigint, "currency" = v_attrs ->> 'currency', "updated_at" = now()
    where x."id" = save_discount_rule.rule and x."tenant_id" = save_discount_rule.tenant
    returning x."id" into v_id;
    if v_id is null then
      raise exception 'discount rule not found' using errcode = 'P0002', hint = 'CATALOG_DISCOUNT_RULE_NOT_FOUND';
    end if;
    return jsonb_build_object('id', v_id, 'created', false);
  end if;
  insert into "better_supabase"."discount_rules" as x ("tenant_id", "customer_group_id", "product_group_id", "valid_from", "valid_to", "min_quantity", "discount_bps", "fixed_price", "currency")
  values (save_discount_rule.tenant, nullif(v_attrs ->> 'customerGroupId', '')::uuid, nullif(v_attrs ->> 'productGroupId', '')::uuid,
    (v_attrs ->> 'validFrom')::date, (v_attrs ->> 'validTo')::date, coalesce((v_attrs ->> 'minQuantity')::numeric, 0),
    coalesce((v_attrs ->> 'discountBps')::integer, 0), (v_attrs ->> 'fixedPrice')::bigint, v_attrs ->> 'currency')
  on conflict ("tenant_id", coalesce("customer_group_id", '00000000-0000-4000-8000-000000000000'::uuid), coalesce("product_group_id", '00000000-0000-4000-8000-000000000000'::uuid), coalesce("valid_from", date '0001-01-01'), "min_quantity") do update set
    "valid_to" = excluded."valid_to", "discount_bps" = excluded."discount_bps", "fixed_price" = excluded."fixed_price",
    "currency" = excluded."currency", "updated_at" = now()
  returning x."id", (xmax = 0) into v_id, v_created;
  return jsonb_build_object('id', v_id, 'created', v_created);
end;
$$;
revoke execute on function "better_supabase"."save_discount_rule"(uuid, uuid, jsonb) from public, anon;
grant execute on function "better_supabase"."save_discount_rule"(uuid, uuid, jsonb) to authenticated, service_role;

-- Deletes a rule of the matrix.
create or replace function "better_supabase"."delete_discount_rule"(rule uuid)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tenant uuid;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select x."tenant_id" into v_tenant from "better_supabase"."discount_rules" x where x."id" = delete_discount_rule.rule;
  if v_tenant is null then
    return false;
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_tenant, 'catalog.manage'), false)) then
    raise exception 'not allowed to manage the catalog' using errcode = '42501', hint = 'CATALOG_FORBIDDEN';
  end if;
  delete from "better_supabase"."discount_rules" x where x."id" = delete_discount_rule.rule;
  return true;
end;
$$;
revoke execute on function "better_supabase"."delete_discount_rule"(uuid) from public, anon;
grant execute on function "better_supabase"."delete_discount_rule"(uuid) to authenticated, service_role;

-- The discount a line gets: { discountBps, fixedPrice, currency, ruleId }.
-- party is the customer's id, product a catalog variant, quantity the line's
-- and on the date the document prices at. A rule applies when its customer
-- group is the party's (or it has none), its product group is the variant's
-- (or it has none), the date is inside its window and quantity reaches its
-- minimum. The most specific rule wins: both groups, then the customer group,
-- then the product group, then neither. Among rules equally specific the
-- highest quantity break wins, then the latest start date. With a currency, a
-- rule whose fixed price is in another currency is skipped. No rule gives a
-- discountBps of 0 and a null ruleId. It reads as the caller.
create or replace function "better_supabase"."resolve_line_discount"(tenant uuid, party text, product uuid, quantity numeric, "on" date, currency text default null)
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
  with scope as (
    select (select x."group_id" from "better_supabase"."discount_group_parties" x where x."tenant_id" = $1 and x."party_id" = $2) as customer_group,
      (select y."discount_group_id" from "better_supabase"."product_variants" y where y."id" = $3 and y."tenant_id" = $1) as item_group
  ),
  matched as (
    select r."id" as id, r."discount_bps" as discount_bps, r."fixed_price" as fixed_price, r."currency" as currency
    from "better_supabase"."discount_rules" r cross join scope s
    where r."tenant_id" = $1
      and (r."customer_group_id" is null or r."customer_group_id" = s.customer_group)
      and (r."product_group_id" is null or r."product_group_id" = s.item_group)
      and (r."valid_from" is null or r."valid_from" <= coalesce($5, current_date))
      and (r."valid_to" is null or r."valid_to" >= coalesce($5, current_date))
      and r."min_quantity" <= coalesce($4, 1)
      and (r."fixed_price" is null or $6 is null or r."currency" = upper($6))
    order by (case when r."customer_group_id" is not null then 2 else 0 end) + (case when r."product_group_id" is not null then 1 else 0 end) desc,
      r."min_quantity" desc, r."valid_from" desc nulls last, r."created_at", r."id"
    limit 1
  )
  select coalesce((select jsonb_build_object('discountBps', m.discount_bps, 'fixedPrice', m.fixed_price::text, 'currency', m.currency, 'ruleId', m.id) from matched m),
    jsonb_build_object('discountBps', 0, 'fixedPrice', null, 'currency', null, 'ruleId', null))
$$;
revoke execute on function "better_supabase"."resolve_line_discount"(uuid, text, uuid, numeric, date, text) from public, anon;
grant execute on function "better_supabase"."resolve_line_discount"(uuid, text, uuid, numeric, date, text) to authenticated, service_role;

-- The import target of the discount_group entity: item.data is { kind, code,
-- name, parties? } where parties lists the ids of a customer group's members
-- and replaces them. A new key with a code the tenant already has for that kind
-- takes over that group.
create or replace function "better_supabase"."import_discount_group"(run uuid, item jsonb, subject_id text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tenant uuid := (import_discount_group.item ->> 'tenant')::uuid;
  v_data jsonb := import_discount_group.item -> 'data';
  v_kind text := v_data ->> 'kind';
  v_code text := btrim(v_data ->> 'code');
  v_name text := btrim(coalesce(v_data ->> 'name', v_data ->> 'code'));
  v_id uuid;
  v_updated timestamptz;
begin
  if v_kind is null or v_kind not in ('customer', 'product') or v_code is null or length(v_code) not between 1 and 50 or length(v_name) not between 1 and 200 then
    raise exception 'a discount group needs a kind (customer or product), a code and a name' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if v_data ? 'parties' and (v_kind <> 'customer' or jsonb_typeof(v_data -> 'parties') <> 'array') then
    raise exception 'parties is a list on a customer group' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if import_discount_group.subject_id is null then
    insert into "better_supabase"."discount_groups" as x ("tenant_id", "kind", "code", "name")
    values (v_tenant, v_kind, v_code, v_name)
    on conflict ("tenant_id", "kind", "code") do update set "name" = excluded."name", "updated_at" = now()
    returning x."id", x."updated_at" into v_id, v_updated;
  else
    begin
      update "better_supabase"."discount_groups" x set "kind" = v_kind, "code" = v_code, "name" = v_name, "updated_at" = now()
      where x."id" = import_discount_group.subject_id::uuid and x."tenant_id" = v_tenant
      returning x."id", x."updated_at" into v_id, v_updated;
    exception when unique_violation then
      raise exception 'another group of this kind has this code' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
    end;
    if v_id is null then
      raise exception 'the discount group no longer exists' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
    end if;
  end if;
  if v_data ? 'parties' then
    delete from "better_supabase"."discount_group_parties" x where x."group_id" = v_id and x."party_id" not in (select jsonb_array_elements_text(v_data -> 'parties'));
    insert into "better_supabase"."discount_group_parties" as x ("tenant_id", "group_id", "party_id")
    select v_tenant, v_id, btrim(p) from jsonb_array_elements_text(v_data -> 'parties') p where length(btrim(p)) between 1 and 200
    on conflict ("tenant_id", "party_id") do update set "group_id" = excluded."group_id";
  end if;
  return jsonb_build_object('subjectId', v_id::text, 'updatedAt', v_updated);
end;
$$;
revoke execute on function "better_supabase"."import_discount_group"(uuid, jsonb, text) from public, anon, authenticated;
grant execute on function "better_supabase"."import_discount_group"(uuid, jsonb, text) to service_role;

-- When a discount group last changed, for the conflict check of imports.
create or replace function "better_supabase"."discount_group_updated_at"(subject_id text)
returns timestamptz
language sql
stable
security definer
set search_path = ''
as $$
  select x."updated_at" from "better_supabase"."discount_groups" x where x."id" = $1::uuid
$$;
revoke execute on function "better_supabase"."discount_group_updated_at"(text) from public, anon, authenticated;
grant execute on function "better_supabase"."discount_group_updated_at"(text) to service_role;

-- The import target of the discount_rule entity: item.data is {
-- customerGroup?, productGroup? (group codes) or customerGroupId?,
-- productGroupId?, validFrom?, validTo?, minQuantity?, discountBps?,
-- fixedPrice?, currency? }. Import groups first.
create or replace function "better_supabase"."import_discount_rule"(run uuid, item jsonb, subject_id text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tenant uuid := (import_discount_rule.item ->> 'tenant')::uuid;
  v_data jsonb := import_discount_rule.item -> 'data';
  v_customer_id uuid;
  v_product_id uuid;
  v_customer_code text := nullif(btrim(v_data ->> 'customerGroup'), '');
  v_product_code text := nullif(btrim(v_data ->> 'productGroup'), '');
  v_customer uuid;
  v_product uuid;
  v_attrs jsonb;
  v_id uuid;
  v_updated timestamptz;
begin
  begin
    v_customer_id := nullif(v_data ->> 'customerGroupId', '')::uuid;
    v_product_id := nullif(v_data ->> 'productGroupId', '')::uuid;
  exception when invalid_text_representation then
    raise exception 'group ids are uuids' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end;
  v_customer := (select y."id" from "better_supabase"."discount_groups" y
      where y."tenant_id" = v_tenant and y."kind" = 'customer'
        and ((v_customer_id is not null and y."id" = v_customer_id) or (v_customer_id is null and v_customer_code is not null and y."code" = v_customer_code)));
  v_product := (select y."id" from "better_supabase"."discount_groups" y
      where y."tenant_id" = v_tenant and y."kind" = 'product'
        and ((v_product_id is not null and y."id" = v_product_id) or (v_product_id is null and v_product_code is not null and y."code" = v_product_code)));
  if (v_customer_id is not null or v_customer_code is not null) and v_customer is null then
    raise exception 'the customer group isn''t in this organization; import the groups first' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if (v_product_id is not null or v_product_code is not null) and v_product is null then
    raise exception 'the product group isn''t in this organization; import the groups first' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  v_attrs := jsonb_strip_nulls(jsonb_build_object('customerGroupId', v_customer, 'productGroupId', v_product, 'validFrom', v_data -> 'validFrom', 'validTo', v_data -> 'validTo',
    'minQuantity', v_data -> 'minQuantity', 'discountBps', v_data -> 'discountBps', 'fixedPrice', v_data -> 'fixedPrice', 'currency', v_data -> 'currency'));
  begin
    perform "better_supabase"."discount_rule_check"(v_tenant, v_attrs);
  exception when sqlstate '22023' or sqlstate 'P0002' then
    raise exception 'the rule isn''t valid: check the groups, dates, discountBps, minQuantity and fixed price' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end;
  if import_discount_rule.subject_id is null then
    insert into "better_supabase"."discount_rules" as x ("tenant_id", "customer_group_id", "product_group_id", "valid_from", "valid_to", "min_quantity", "discount_bps", "fixed_price", "currency")
    values (v_tenant, v_customer, v_product, (v_attrs ->> 'validFrom')::date, (v_attrs ->> 'validTo')::date, coalesce((v_attrs ->> 'minQuantity')::numeric, 0),
      coalesce((v_attrs ->> 'discountBps')::integer, 0), (v_attrs ->> 'fixedPrice')::bigint, v_attrs ->> 'currency')
    on conflict ("tenant_id", coalesce("customer_group_id", '00000000-0000-4000-8000-000000000000'::uuid), coalesce("product_group_id", '00000000-0000-4000-8000-000000000000'::uuid), coalesce("valid_from", date '0001-01-01'), "min_quantity") do update set
      "valid_to" = excluded."valid_to", "discount_bps" = excluded."discount_bps", "fixed_price" = excluded."fixed_price",
      "currency" = excluded."currency", "updated_at" = now()
    returning x."id", x."updated_at" into v_id, v_updated;
  else
    begin
      update "better_supabase"."discount_rules" x set "customer_group_id" = v_customer, "product_group_id" = v_product, "valid_from" = (v_attrs ->> 'validFrom')::date, "valid_to" = (v_attrs ->> 'validTo')::date,
        "min_quantity" = coalesce((v_attrs ->> 'minQuantity')::numeric, 0), "discount_bps" = coalesce((v_attrs ->> 'discountBps')::integer, 0),
        "fixed_price" = (v_attrs ->> 'fixedPrice')::bigint, "currency" = v_attrs ->> 'currency', "updated_at" = now()
      where x."id" = import_discount_rule.subject_id::uuid and x."tenant_id" = v_tenant
      returning x."id", x."updated_at" into v_id, v_updated;
    exception when unique_violation then
      raise exception 'another rule has the same groups, start date and minimum quantity' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
    end;
    if v_id is null then
      raise exception 'the discount rule no longer exists' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
    end if;
  end if;
  return jsonb_build_object('subjectId', v_id::text, 'updatedAt', v_updated);
end;
$$;
revoke execute on function "better_supabase"."import_discount_rule"(uuid, jsonb, text) from public, anon, authenticated;
grant execute on function "better_supabase"."import_discount_rule"(uuid, jsonb, text) to service_role;

