-- A product's text and its variants' titles in locale: the locale itself,
-- then its language, then the default locale's text on the product. Runs
-- as the caller, so the read policies decide what it sees.
create or replace function "app_private"."product_text"(product uuid, locale text default null)
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
  select jsonb_build_object(
    'id', p."id",
    'slug', p."slug",
    'locale', (case when $2 = any ('{en}'::text[]) then $2 when split_part($2, '-', 1) = any ('{en}'::text[]) then split_part($2, '-', 1) else 'en' end),
    'title', coalesce(t."title", p."title"),
    'description', coalesce(t."description", p."description"),
    'variants', coalesce((
      select jsonb_agg(jsonb_build_object('id', w."id", 'sku', w."sku", 'title', coalesce((select y."title" from "app_private"."product_variant_translations" y where y."variant_id" = w."id" and y."locale" = (case when $2 = any ('{en}'::text[]) then $2 when split_part($2, '-', 1) = any ('{en}'::text[]) then split_part($2, '-', 1) else 'en' end)), w."title")) order by w."rank" collate "C", w."id")
      from "app_private"."product_variants" w where w."product_id" = p."id"
    ), '[]'::jsonb)
  )
  from "app_private"."products" p
  left join "app_private"."product_translations" t on t."product_id" = p."id" and t."locale" = (case when $2 = any ('{en}'::text[]) then $2 when split_part($2, '-', 1) = any ('{en}'::text[]) then split_part($2, '-', 1) else 'en' end)
  where p."id" = $1
$$;
revoke execute on function "app_private"."product_text"(uuid, text) from public;
